// <autogenerated />
using Microsoft.AspNetCore.Components;
using Shared.DTO.ApplicationUser;
using Shared.DTO.Customer;
using Shared.DTO.Departments;
using System.Net.Http.Json;

namespace HandymanWorkshop.Client.Pages.Profiles
{
    public partial class Create
    {
        ApplicationNewUserDto newProfiles { get; set; } = new ApplicationNewUserDto();

        [Inject]
        protected NavigationManager? NavMan { get; set; }

        protected async Task AddProfiles()
        {
            var response = await Http.PostAsJsonAsync("api/Profiles", newProfiles);
            if (response.IsSuccessStatusCode)
            {
                NavMan.NavigateTo("/Profiles");
            }
            else
            {
                Console.WriteLine($"Error >> {response.ReasonPhrase}");
            }

        }
    }
}
